            )
            if done:
                break
            state = next_state

        advantages = [0.0] * len(trajectory)
        a_t = 0.0
        for t in range(len(trajectory) - 1, -1, -1):
            (
                _s,
                _a,
                reward,
                _old_logp,
                value,
                value_next,
                _done,
            ) = trajectory[t]
            delta = reward + gamma * value_next - value
            if not math.isfinite(delta):
